-- Name: Cohorted Deals Numerator_denominator - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH srp_sd AS ( SELECT s.mri_session_id, s.route_id, CAST(s.doj AS VARCHAR) AS doj, s.cohort_type, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant FROM "user_interaction"."search_route_details" s WHERE __time >= TIMESTAMP '2026-04-28 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND s.country = 'IND' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'iOS' AND s.tp_channel = 'INVALID' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 ), -- One variant per session (Pokus-stable; tie-break is arbitrary if ever duplicated) session_variant AS ( SELECT m.mri_session_id, MAX(m.exp_variant) AS exp_variant FROM srp_sd m GROUP BY 1 ), -- Offer tuple routes per variant: boosted at least once in-window on Same-Day SRP offer_tuple_routes AS ( SELECT DISTINCT m.exp_variant, m.route_id FROM srp_sd m WHERE m.cohort_type = 'BOOSTUI' ), boost_seen_sessions AS ( SELECT DISTINCT m.mri_session_id FROM srp_sd m WHERE m.cohort_type = 'BOOSTUI' ), sl_base AS ( SELECT sld.mri_session_id, sld.route_id, CAST(sld.doj AS VARCHAR) AS doj FROM "user_interaction"."seat_layout_details" sld WHERE __time >= TIMESTAMP '2026-04-28 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND sld.country = 'IND' ), sl_enriched AS ( SELECT sl.mri_session_id, sl.route_id, sv.exp_variant, CASE WHEN bs.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS is_boost_seen_session, CASE WHEN otr.route_id IS NOT NULL THEN 1 ELSE 0 END AS is_offer_tuple_route FROM sl_base sl INNER JOIN session_variant sv ON sv.mri_session_id = sl.mri_session_id LEFT JOIN boost_seen_sessions bs ON bs.mri_session_id = sl.mri_session_id LEFT JOIN offer_tuple_routes otr ON otr.route_id = sl.route_id AND otr.exp_variant = sv.exp_variant ), confirm_ok AS ( SELECT DISTINCT c.mri_session_id, c.route_id, CAST(c.doj AS VARCHAR) AS doj, c.tin FROM "user_interaction"."confirm_order_details" c WHERE __time >= TIMESTAMP '2026-04-28 18:30:00' AND __time < TIMESTAMP '2026-04-29 18:30:00' AND c.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND c.country = 'IND' AND c.status = 200 AND c.tin IS NOT NULL AND c.tin NOT IN ('', 'null') ), confirm_enriched AS ( SELECT co.mri_session_id, co.route_id, co.doj, co.tin, sv.exp_variant, CASE WHEN bs.mri_session_id IS NOT NULL THEN 1 ELSE 0 END AS is_boost_seen_session, CASE WHEN otr.route_id IS NOT NULL THEN 1 ELSE 0 END AS is_offer_tuple_route FROM confirm_ok co INNER JOIN session_variant sv ON sv.mri_session_id = co.mri_session_id LEFT JOIN boost_seen_sessions bs ON bs.mri_session_id = co.mri_session_id LEFT JOIN offer_tuple_routes otr ON otr.route_id = co.route_id AND otr.exp_variant = sv.exp_variant ) SELECT '28 to 29 Appril' AS month_period, sv.exp_variant, /* ---------- Boost seen · Click share (actuals) ---------- */ SUM(CASE WHEN se.is_boost_seen_session = 1 THEN 1 ELSE 0 END) AS boost_seen_sl_land_instances_denominator, COUNT(DISTINCT CASE WHEN se.is_boost_seen_session = 1 THEN se.mri_session_id END) AS boost_seen_sl_land_sessions_denominator, SUM(CASE WHEN se.is_boost_seen_session = 1 AND se.is_offer_tuple_route = 1 THEN 1 ELSE 0 END) AS boost_seen_offer_tuple_sl_land_instances_numerator, COUNT(DISTINCT CASE WHEN se.is_boost_seen_session = 1 AND se.is_offer_tuple_route = 1 THEN se.mri_session_id END) AS boost_seen_offer_tuple_sl_land_sessions_numerator, /* ---------- Overall · Click share (actuals) ---------- */ COUNT(*) AS overall_sl_land_instances_denominator, COUNT(DISTINCT se.mri_session_id) AS overall_sl_land_sessions_denominator, SUM(CASE WHEN se.is_offer_tuple_route = 1 THEN 1 ELSE 0 END) AS overall_offer_tuple_sl_land_instances_numerator, COUNT(DISTINCT CASE WHEN se.is_offer_tuple_route = 1 THEN se.mri_session_id END) AS overall_offer_tuple_sl_land_sessions_numerator, /* ---------- Boost seen · Order share (actuals) ---------- */ COUNT(DISTINCT CASE WHEN ce.is_boost_seen_session = 1 THEN ce.mri_session_id END) AS boost_seen_confirm_sessions_denominator, COUNT(DISTINCT CASE WHEN ce.is_boost_seen_session = 1 THEN ce.tin END) AS boost_seen_confirm_tins_denominator, COUNT(DISTINCT CASE WHEN ce.is_boost_seen_session = 1 AND ce.is_offer_tuple_route = 1 THEN ce.mri_session_id END) AS boost_seen_offer_tuple_confirm_sessions_numerator, COUNT(DISTINCT CASE WHEN ce.is_boost_seen_session = 1 AND ce.is_offer_tuple_route = 1 THEN ce.tin END) AS boost_seen_offer_tuple_confirm_tins_numerator, /* ---------- Overall · Order share (actuals) ---------- */ COUNT(DISTINCT ce.mri_session_id) AS overall_confirm_sessions_denominator, COUNT(DISTINCT ce.tin) AS overall_confirm_tins_denominator, COUNT(DISTINCT CASE WHEN ce.is_offer_tuple_route = 1 THEN ce.mri_session_id END) AS overall_offer_tuple_confirm_sessions_numerator, COUNT(DISTINCT CASE WHEN ce.is_offer_tuple_route = 1 THEN ce.tin END) AS overall_offer_tuple_confirm_tins_numerator FROM session_variant sv LEFT JOIN sl_enriched se ON se.mri_session_id = sv.mri_session_id AND se.exp_variant = sv.exp_variant LEFT JOIN confirm_enriched ce ON ce.mri_session_id = sv.mri_session_id AND ce.exp_variant = sv.exp_variant GROUP BY 1, 2 ORDER BY 1, 2
